  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '5.6') IS DISTINCT FROM '6558fc7d02fc8b3d6d3d864e4231566b' THEN RAISE EXCEPTION 'el guion del 5.6 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '5.8') IS DISTINCT FROM '74b8703c1a964b330461af317937e47b' THEN RAISE EXCEPTION 'el guion del 5.8 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '5.10') IS DISTINCT FROM '95fb7f1159182733968831cfc323ac1a' THEN RAISE EXCEPTION 'el guion del 5.10 no quedó'; END IF;
