  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '5.13') IS DISTINCT FROM 'c6328cdb2431115bff615b1d56b43974' THEN RAISE EXCEPTION 'el guion del 5.13 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '5.14') IS DISTINCT FROM 'ffe498db2efc878c3e4ffe0aacae80a1' THEN RAISE EXCEPTION 'el guion del 5.14 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '5.15') IS DISTINCT FROM '437e13a52013d1f11592cb912834d220' THEN RAISE EXCEPTION 'el guion del 5.15 no quedó'; END IF;
